import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:pagashell/domain/terminal/terminal_frame.dart';

/// Generated by the Rust golden test; never synthesize ANSI parsing in Dart.
List<TerminalFrame> nativeTerminalFrames({
  String path = 'test/fixtures/native_terminal_frames.json',
}) {
  final frames = jsonDecode(File(path).readAsStringSync()) as List<Object?>;
  return [for (final raw in frames) _frame(raw! as Map<String, Object?>)];
}

TerminalFrame _frame(Map<String, Object?> frame) => TerminalFrame(
  columns: frame['columns']! as int,
  rows: frame['rows']! as int,
  alternate: frame['alternate']! as bool,
  cursorX: frame['cursor_x']! as int,
  cursorY: frame['cursor_y']! as int,
  modes: frame['modes']! as int,
  cursorBlink: frame['cursor_blink']! as bool,
  trimFront: frame['trim_front']! as int,
  keepRows: frame['keep_rows']! as int,
  appendRows: (frame['append_rows']! as List<Object?>).cast<int>(),
  lines: [
    for (final raw in frame['lines']! as List<Object?>)
      _line(raw! as Map<String, Object?>),
  ],
  title: frame['title'] as String?,
  bell: frame['bell']! as bool,
);

TerminalLine _line(Map<String, Object?> line) => TerminalLine(
  id: line['id']! as int,
  wrapped: line['wrapped']! as bool,
  cells: Uint32List.fromList((line['cells']! as List<Object?>).cast<int>()),
  clusters: {
    for (final raw in line['clusters']! as List<Object?>)
      (raw! as Map<String, Object?>)['column']! as int:
          (raw as Map<String, Object?>)['text']! as String,
  },
);
